package designsystem

import (
	"fmt"
	"html/template"
	"sync"
)

// ── The gallery's own words ──────────────────────────────────────────
//
// Everything the framework itself says on this page — a button's label,
// a field's error, a shell's skip link — comes out of the base catalog
// through T, and has since the tree was first rendered. This file is
// the other half: the words the *page* says, in its own voice. The
// section headings, the explanation under each one, the note beside a
// sample, the labels on the three switchers.
//
// They used to be English literals in the template, and the page said
// so out loud: "the components speak Japanese; the prose around them
// stays in English". That sentence is gone, and this file is why. A
// gallery whose language switcher changes the buttons and leaves the
// paragraphs is not showing you the framework in Japanese — it is
// showing you an English document with Japanese components in it, which
// is a different and much less useful thing.
//
// ── The key is the English ───────────────────────────────────────────
//
// prose maps the English source string to its eleven translations. The
// key is the sentence itself rather than a slug, which is a deliberate
// choice with three consequences worth stating:
//
//   - samples.go stays readable. Its state labels and notes ARE its
//     documentation — the file's own comment says the judgement is the
//     documentation — and "sample.field_select.plain_opt_out" is not a
//     judgement anybody can read.
//   - a missing translation degrades to English rather than to a slug
//     shown to a reader. The parity gate below fails the build either
//     way, so nobody ships it; the difference is what a half-finished
//     working copy looks like.
//   - the leak gate gets teeth. Because every key IS an English string
//     the page can emit, the gate can assert that NONE of them appears
//     on the Japanese page — a hundred and eighty sentinels rather than
//     three. See TestNoEnglishProseReachesATranslatedPage.
//
// en is therefore not stored: proseIn returns the key unchanged for it.
// "Every key in twelve locales" still means exactly what it says — the
// gate walks all twelve — it is only the twelfth that costs no bytes.
//
// ── The register ─────────────────────────────────────────────────────
//
// Machine-drafted from the English, in the same register as the base
// catalogs in locales/*.toml: calm, plain, second person where the
// language has one, no exclamation, no marketing. A native speaker's
// correction is welcome. Two rules the drafts keep:
//
//   - identifiers are not translated. rst-box, select.js, data-poll,
//     aria-current, method="get", ui.Layout, tokens.css and the partial
//     names are code, and a reader looking one up needs the string that
//     is actually in the file.
//   - {placeholders} survive verbatim, in whatever position the target
//     language puts them. interpolate leaves an unmatched one on the
//     page rather than deleting half a sentence, so a typo here shows
//     up as "{shel}" in the gallery instead of silently vanishing.

// proseIn returns one gallery string in one locale, with {name}
// placeholders substituted from alternating name/value arguments the
// way T does.
//
// The empty string in is the empty string out: several call sites pass
// an optional field (a sample's Note) straight through, and an empty
// note must stay empty rather than becoming a lookup nobody wrote.
func proseIn(locale, en string, args ...any) string {
	if en == "" || proseCode[en] {
		return en
	}
	trace(en)
	s := en
	if locale != "en" {
		if t, ok := prose[en][locale]; ok && t != "" {
			s = t
		}
	}
	return interpolate(s, args)
}

// proseCode is the short list of strings the renderer emits that are
// code wearing the shape of a word. The four tone names label the tone
// samples, and they are the same four words the class names carry
// (rst-tone-positive) and the same four a caller passes as Tone —
// translating them would leave a Spanish reader looking at "positivo"
// and typing "positive", which is worse documentation, not better.
//
// They are exempt from the parity gate and from the leak gate, which
// is the whole reason the list is here rather than being a judgement
// each gate makes for itself.
var proseCode = map[string]bool{
	"neutral":  true,
	"positive": true,
	"warning":  true,
	"negative": true,
	"info":     true,
}

// proseMarkup is proseIn for the one sentence whose placeholders are
// filled with markup rather than with text: the page's opening line,
// which puts the theme name in <strong> and the language's autonym in a
// <strong lang=…> so a screen reader switches voice to say it.
//
// The order is the whole of it. The prose is escaped FIRST, as the
// text it is, and the markup values are substituted into the escaped
// result — so a translator who writes an ampersand gets &amp; and the
// two <strong> elements stay elements. Doing it the other way round,
// or marking the whole assembled string safe, would make every entry in
// this file a place to write markup, which is not a promise a
// translation table should make.
func proseMarkup(locale, en string, args ...any) template.HTML {
	trace(en)
	s := en
	if locale != "en" {
		if t, ok := prose[en][locale]; ok && t != "" {
			s = t
		}
	}
	escaped := template.HTMLEscapeString(s)
	values := make([]any, len(args))
	copy(values, args)
	for i := 1; i < len(values); i += 2 {
		// A value that is already markup goes in as it is; anything
		// else is text and is escaped, so the only way to put an
		// element on the page is to say so at the call site.
		if h, ok := values[i].(template.HTML); ok {
			values[i] = string(h)
			continue
		}
		values[i] = template.HTMLEscapeString(fmt.Sprint(values[i]))
	}
	return template.HTML(interpolate(escaped, values))
}

// ── The tracer ───────────────────────────────────────────────────────
//
// Every prose lookup the renderer makes is announced to traceFn when a
// test has installed one. That is how TestEveryProseKeyIsTranslated
// knows the key set it has to check: not a list somebody maintains
// beside this file, which would go stale the first time a sample gained
// a note, but the keys a full Render actually asked for.

var (
	traceMu sync.Mutex
	traceFn func(string)
)

func trace(en string) {
	traceMu.Lock()
	fn := traceFn
	traceMu.Unlock()
	if fn != nil {
		fn(en)
	}
}

// setProseTrace installs a tracer and returns a function that removes
// it. Test-only, and unexported: nothing outside this package renders
// this page.
func setProseTrace(fn func(string)) func() {
	traceMu.Lock()
	traceFn = fn
	traceMu.Unlock()
	return func() {
		traceMu.Lock()
		traceFn = nil
		traceMu.Unlock()
	}
}

// prose is the table: English source → locale code → translation. See
// the file comment above for why the key is the English sentence and
// why en is absent from every row.
//
// Every string in it is a raw literal, keys and values alike, because a
// good number of them quote an attribute — role="alert",
// data-rst-select="false", method="get" — and a table where some entries
// escape their quotes and others do not is a table where the next person
// guesses. No string here contains a backtick; if one ever needs to,
// that entry alone becomes an interpreted literal.
